const { execSync } = require('child_process');
const fs = require('fs');

// CONFIGURACIÓN DE RUTAS (Asegúrate de que coincidan con tu PC)
const FFUF_PATH = 'C:\\Herramientas\\ffuf_2.1.0_windows_amd64\\ffuf.exe';
const WORDLIST = 'C:\\Herramientas\\common.txt';
const TARGET = $('Loop Over Items').first().json.target
const OUTPUT_FILE = 'C:\\Herramientas\\ffuf_results.json';
const PHPSESSID = $('URL Ejemplo').first().json.phpsessionID;

try {
  // Ejecutar ffuf
  // -s: Modo silencioso para no ensuciar la consola

  const ffufCommand = `ffuf -u ${TARGET}/FUZZ -w ${WORDLIST} -mc 200,204,301,302,307,401,403 -s -of json -o ${OUTPUT_FILE} -t 100 -timeout 15 -H "Cookie: PHPSESSID=${PHPSESSID}; security=low"`;

  console.log("Ejecutando ffuf...");
  execSync(ffufCommand);

  // Leer y parsear los resultados
  const rawData = fs.readFileSync(OUTPUT_FILE, 'utf8');
  const results = JSON.parse(rawData);

  return [{
    json: {
      message: "Fuzzing de directorios completado",
      ffufResults: results.results || [],
    discoveredPaths: results.results ? results.results.length : 0,
      totalFound: results.results.length,
      url: ffufCommand
    }
  }];

} catch (error) {
  return [{ json: { error: "Error en ffuf: " + error.message } }];
}

const axios = require('axios');

const ZAP_API_KEY = $('Loop Over Items').first().json.zap_api_key;
const ZAP_URL = $('Loop Over Items').first().json.zap_url;
const TARGET_URL = $('Loop Over Items').first().json.target;

try {
  console.log("Iniciando Escaneo Activo (Active Scan)...");

  // 1. Iniciar el Escaneo Activo
  // Nota: ZAP usará automáticamente la sesión (Cookie) porque inyectamos 
  // la regla Replacer globalmente en el nodo del Spider.
  const activeScanResponse = await axios.get(`${ZAP_URL}/JSON/ascan/action/scan/`, {
    params: {
      apikey: ZAP_API_KEY,
      url: TARGET_URL,
      recurse: true,
      inScopeOnly: false
    }
  });

  const activeScanId = activeScanResponse.data.scan;
  console.log(`Active Scan ID: ${activeScanId}. Esperando a que finalice...`);

  // 2. Bucle de espera (con límite de seguridad para evitar cuelgues infinitos)
  let progress = 0;
  let intentos = 0;
  const startTime = Date.now();
  const MAX_TIMEOUT_MS = 4.7 * 60 * 1000;
  const MAX_INTENTOS = 360; // 360 intentos * 5 seg = 30 minutos de máximo. 

  while (progress < 100 && (Date.now() - startTime) < MAX_TIMEOUT_MS) {
    // Espera de 5 segundos
    await new Promise(resolve => setTimeout(resolve, 5000));

    try {
        const statusResponse = await axios.get(`${ZAP_URL}/JSON/ascan/view/status/`, {
            params: { apikey: ZAP_API_KEY, scanId: activeScanId }
        });

        progress = parseInt(statusResponse.data.status);
    } catch (error) {
        console.error("Error temporal al consultar ZAP:", error.message);
        // Si hay un error de red, no rompemos el nodo, dejamos que intente de nuevo en 5s.
    }

    intentos++;

    // Logueamos solo cada 30 segundos (aprox 6 intentos) para no saturar la consola de n8n
    if (intentos % 6 === 0 || progress === 100) { 
        const elapsedSeconds = Math.round((Date.now() - startTime) / 1000);
        console.log(`Progreso Escaneo Activo: ${progress}% (Tiempo transcurrido: ${elapsedSeconds}s)`);
    }
  }

  console.log("Obteniendo alertas de ZAP...");

  // 3. Obtener alertas (Solo consulta la BD de ZAP, no requiere Headers de sesión)
  const response = await axios.get(`${ZAP_URL}/JSON/core/view/alerts/`, {
    params: {
      apikey: ZAP_API_KEY,
      baseurl: TARGET_URL
    }
  });

  // Filtramos como tenías antes (pluginId >= 100000 suele separar activas de pasivas)
  const rawAlerts = response.data.alerts || [];

  // ==========================================
  // MAGIA ANTI-MEMORIA: DEDUPLICACIÓN DE ALERTAS
  // ==========================================
  // Nos aseguramos de no procesar 1000 veces la misma alerta exacta en la misma URL
  const uniqueAlertsMap = new Map();

  rawAlerts.forEach(a => {
    const uniqueKey = `${a.alert}_${a.url}`; // Llave única: Nombre de vulnerabilidad + URL

    if (!uniqueAlertsMap.has(uniqueKey)) {
      uniqueAlertsMap.set(uniqueKey, {
        risk: a.risk,
        name: a.alert,
        url: a.url,
        evidence: a.evidence || 'N/A',
        description: a.description,
        alert: a.alert,
        solution: a.solution,
        cweid: a.cweid
      });
    }
  });

  // Convertimos el Map limpio de vuelta a un Array
  const allAlerts = Array.from(uniqueAlertsMap.values());

  // 4. Retornamos los datos respetando tu estructura exacta
  return [{
    json: {
      message: progress >= 100 ? "Alertas obtenidas con éxito" : "Escaneo detenido por límite de tiempo (Timeout)",
      totalAlerts: allAlerts.length,
      highRisk: allAlerts.filter(a => a.risk === 'High').length,
      mediumRisk: allAlerts.filter(a => a.risk === 'Medium').length,
      full: rawAlerts,  // Mantiene la lista cruda completa (por si la necesitas de respaldo)
      allAlerts: allAlerts // Manda la lista limpia y procesada para los nodos siguientes
    }
  }];

} catch (error) {
  return [{ json: { error: "Error en Active Scan: " + error.message } }];
}

