const axios = require('axios');

const ZAP_API_KEY = $('URL Ejemplo').first().json.zap_api_key;
const ZAP_URL = $('URL Ejemplo').first().json.zap_url;
const TARGET_URL = $('Loop Over Items').first().json.target;
const PHPSESSID = $('URL Ejemplo').first().json.phpsessionID;

const COOKIE_AUTH = `PHPSESSID=${PHPSESSID}; security=low`;

try {
  console.log("Preparando entorno limpio en ZAP...");

  // ==========================================
  // FIX 1: Crear una sesión nueva en ZAP para borrar el caché del árbol de sitios
  // Esto asegura que ZAP empiece de cero y vuelva a escanear todo.
  // ==========================================
  await axios.get(`${ZAP_URL}/JSON/core/action/newSession/`, {
    params: { apikey: ZAP_API_KEY, name: 'n8n_Fuzzing_Session', overwrite: 'true' }
  });

  // ==========================================
  // FIX 2: Excluir URLs destructivas del Spider
  // Evitamos que ZAP visite logout.php (mata la sesión) y setup.php (resetea DVWA)
  // ==========================================
  const exclusions = ['.*logout.*', '.*setup\\.php.*'];
  for (const regex of exclusions) {
    await axios.get(`${ZAP_URL}/JSON/spider/action/excludeFromScan/`, {
      params: { apikey: ZAP_API_KEY, regex: regex }
    });
  }

  console.log("Configurando sesión (Replacer) en ZAP...");

  // 1. LIMPIEZA PREVIA del Replacer
  try {
    await axios.get(`${ZAP_URL}/JSON/replacer/action/removeRule/`, {
      params: { apikey: ZAP_API_KEY, description: 'Sesion_DVWA' }
    });
  } catch (e) {
    // Si la regla no existía, ignoramos
  }

  // 2. Inyectar la Cookie globalmente
  await axios.get(`${ZAP_URL}/JSON/replacer/action/addRule/`, {
   params: {
     apikey: ZAP_API_KEY,
     description: 'Sesion_DVWA',
     enabled: 'true',
     matchType: 'REQ_HEADER',
     matchRegex: 'false',
     matchString: 'Cookie',
     replacement: COOKIE_AUTH
   }
  });

  // 3. Iniciar el Spider
  const spiderResponse = await axios.get(`${ZAP_URL}/JSON/spider/action/scan/`, {
    params: {
      apikey: ZAP_API_KEY,
      url: TARGET_URL,
      maxChildren: 10,
      recurse: true
    }
  });

  const scanId = spiderResponse.data.scan;
  console.log(`Iniciando Spider... ID: ${scanId}`);

  // 4. Bucle de espera hasta que el Spider termine
  let progress = 0;
  while (progress < 100) {
    await new Promise(resolve => setTimeout(resolve, 2000));

    const statusResponse = await axios.get(`${ZAP_URL}/JSON/spider/view/status/`, {
      params: { apikey: ZAP_API_KEY, scanId: scanId }
    });

    progress = parseInt(statusResponse.data.status);
    console.log(`Progreso ZAP: ${progress}%`);
  }

  // 5. Extraer los resultados
  const urlsResponse = await axios.get(`${ZAP_URL}/JSON/spider/view/results/`, {
    params: { apikey: ZAP_API_KEY, scanId: scanId }
  });

  const rawUrls = urlsResponse.data.results || [];

  // Usamos Set para eliminar todas las URLs repetidas. 
  const uniqueUrls = [...new Set(rawUrls)];

  return [{
    json: {
      message: "Spider completado con sesión activa y entorno limpio",
      urlsFound: uniqueUrls,
      count: uniqueUrls.length
    }
  }];

} catch (error) {
  // Mejora opcional: imprimir el error exacto de Axios si existe
  const errorMsg = error.response ? JSON.stringify(error.response.data) : error.message;
  return [{ json: { error: errorMsg } }];
}
